import{_ as e,o as t,c as r,a2 as o}from"./chunks/framework.ClgMjOt7.js";const _=JSON.parse('{"title":"アプリロックと電卓偽装","description":"PIN ロック、生体認証、電卓偽装機能、スクショ防止","frontmatter":{"title":"アプリロックと電卓偽装","description":"PIN ロック、生体認証、電卓偽装機能、スクショ防止"},"headers":[],"relativePath":"user/security.md","filePath":"user/security.md","lastUpdated":1789105872000}'),i={name:"user/security.md"};function l(s,a,n,c,d,h){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="アプリロックと電卓偽装" tabindex="-1">アプリロックと電卓偽装 <a class="header-anchor" href="#アプリロックと電卓偽装" aria-label="Permalink to &quot;アプリロックと電卓偽装&quot;">​</a></h1><p>Palleria には、プライベートな鑑賞を守るためのセキュリティ機能が備わっています。</p><hr><h2 id="アプリロック" tabindex="-1">アプリロック <a class="header-anchor" href="#アプリロック" aria-label="Permalink to &quot;アプリロック&quot;">​</a></h2><ul><li><strong>PIN コード</strong>: 4〜8 桁の暗証番号を設定してアプリ起動時にロックをかけられます。</li><li><strong>指紋・顔認証</strong>: スマホの指紋センサーや顔認証でスムーズにロック解除できます。</li><li><strong>自動ロック</strong>: アプリを閉じてから指定した時間（即時〜10分）が経つと、自動的にロックがかかります。</li></ul><hr><h2 id="電卓偽装機能" tabindex="-1">電卓偽装機能 <a class="header-anchor" href="#電卓偽装機能" aria-label="Permalink to &quot;電卓偽装機能&quot;">​</a></h2><p>アプリの見た目を「本物の電卓」に化けさせる機能です。他人にスマホを見られたときでも安全です。</p><ul><li><strong>本物として計算できる電卓</strong>: 実際に入力して計算ができる偽装画面が表示されます。</li><li><strong>秘密の解除方法</strong>: 設定した番号を入力して <code>=</code> ボタンを押すことで、はじめて Palleria 本体の画面が開きます。</li><li><strong>アイコンと名前の変更</strong>: ホーム画面上のアプリ名も「電卓」という名前に変わります。</li></ul><hr><h2 id="スクリーンショット保護" tabindex="-1">スクリーンショット保護 <a class="header-anchor" href="#スクリーンショット保護" aria-label="Permalink to &quot;スクリーンショット保護&quot;">​</a></h2><p>設定から画面保護を有効にすると、スクリーンショットの撮影や画面録画を防止できます。また、スマホのタスク切替画面でアプリの中身が映らないようにぼかしがかかります。</p>',12)])])}const p=e(i,[["render",l]]);export{_ as __pageData,p as default};
